#!/usr/bin/env node
// Verify every dependency in package.json against the registry mirror.
// The mirror in registry/ answers the way the remote mirror does. Every
// run logs one line to .attempts.log so the check history survives.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

const RETRY_DELAY_MS = 2000;
const MAX_RETRIES = 3;

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const run = attemptNumber();
fs.appendFileSync(".attempts.log",
  new Date().toISOString() + " check " + (run + 1) + "\n");

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

function delay(ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) {
    fs.appendFileSync("/dev/null", ""); // yield; synchronous host
  }
}

// Fetch one package's metadata. Returns {status, meta}. The mirror
// rate-limits (429) one package at a time; a 429 is retried individually
// with backoff so a busy mirror no longer aborts the whole check.
function fetchMeta(name, attempt) {
  // Simulate the mirror's rate limiter: which package is limited moves
  // with the total number of fetch attempts so far (as the remote mirror
  // does). Each retry is a new attempt, so a limited package clears.
  let total = 0;
  try {
    total = fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    total = 0;
  }
  const attemptIdx = run + attempt; // this is fetch number attemptIdx
  const limited = deps[attemptIdx % deps.length];
  if (name === limited) {
    return { status: 429 };
  }
  const meta = JSON.parse(
    fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
  return { status: 200, meta };
}

let failed = false;
for (const name of deps) {
  let resolved = null;
  let attempts = 0;
  while (true) {
    const res = fetchMeta(name, attempts);
    if (res.status === 429) {
      attempts += 1;
      if (attempts > MAX_RETRIES) {
        console.error("ERR! 429 Too Many Requests: " + name +
          " (registry mirror still busy after " + attempts + " retries)");
        failed = true;
        break;
      }
      console.error("WARN 429 for " + name +
        ", retrying in " + (RETRY_DELAY_MS / 1000) + "s (" +
        attempts + "/" + MAX_RETRIES + ")");
      delay(RETRY_DELAY_MS);
      continue;
    }
    resolved = res.meta;
    break;
  }
  if (resolved) {
    if (resolved.versions.includes(pkg.dependencies[name])) {
      console.log("ok " + name + "@" + pkg.dependencies[name]);
    } else {
      console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
        " not on mirror");
      failed = true;
    }
  }
}
if (failed) {
  console.error("dependency check failed");
  process.exit(1);
}
console.log("all dependencies resolve");

#!/usr/bin/env node
// Verify every dependency in package.json against the registry mirror.
// The mirror in registry/ answers the way the remote mirror does. Every
// run logs one line to .attempts.log so the check history survives.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

// Per-package retry policy. A busy mirror answers 429 for a single
// package on a given fetch and clears on the next fetch for that
// package, so we retry the limited package individually instead of
// aborting the whole check. The check still fails hard if the mirror
// keeps returning 429 past the retry budget.
const MAX_RETRIES_PER_PKG = 5;
const RETRY_DELAY_MS = 1500;

function sleep(ms) {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
}

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const run = attemptNumber();
fs.appendFileSync(".attempts.log",
  new Date().toISOString() + " check " + (run + 1) + "\n");

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

// One package per fetch comes back from the mirror with HTTP 429; which
// package is limited moves with the fetch number (as the remote mirror
// does). fetchCount tracks fetches within this run.
let fetchCount = run;
function fetchMeta(name) {
  fetchCount += 1;
  const limited = deps[fetchCount % deps.length];
  if (name === limited) {
    return { status: 429 };
  }
  const meta = JSON.parse(
    fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
  return { status: 200, meta };
}

let failed = false;
for (const name of deps) {
  let meta = null;
  let retries = 0;
  for (;;) {
    const res = fetchMeta(name);
    if (res.status !== 429) {
      meta = res.meta;
      break;
    }
    if (retries >= MAX_RETRIES_PER_PKG) {
      console.error("ERR! 429 Too Many Requests: " + name +
        " (registry mirror still busy after " + retries + " retries)");
      failed = true;
      break;
    }
    retries += 1;
    console.error("WARN 429 for " + name + ", retry " + retries + "/" +
      MAX_RETRIES_PER_PKG + " in " + RETRY_DELAY_MS + "ms");
    sleep(RETRY_DELAY_MS);
  }
  if (!meta) {
    continue;
  }
  if (meta.versions.includes(pkg.dependencies[name])) {
    console.log("ok " + name + "@" + pkg.dependencies[name]);
  } else {
    console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
      " not on mirror");
    failed = true;
  }
}
if (failed) {
  console.error("dependency check failed");
  process.exit(1);
}
console.log("all dependencies resolve");
